\title{Polynomial-Size Witnesses for the Colorful Carath\'eodory Theorem
over Spanning $k$-Trees}
\author{Aristotle}
\date{July 14, 2026}

\begin{document}
\maketitle

\begin{abstract}
The colorful Carath\'eodory theorem of B\'ar\'any asserts that if
$V_1, \dots, V_{d+1}$ are point sets in $\R^d$, each of whose convex hull
contains a common target $p$, then there exists a \emph{rainbow} simplex --- one
vertex per color class --- whose convex hull also contains $p$. Combinatorially,
this rainbow simplex is a face of the join $V_1 * \cdots * V_{d+1}$, an object
with $\prod_i |V_i|$ top-dimensional faces and hence an exponential search space.
We study the \emph{witness complexity} hiding behind this qualitative statement:
how large a sub-collection of faces must one retain to guarantee that a
$p$-capturing face lies within it? We prove that any abstract complex whose faces
have width at most $k+1$ (in particular, any $d$-dimensional spanning $k$-tree) on
an $n$-vertex ground set has face count exactly $\sum_{i=0}^{k+1}\binom{n}{i}$, a
polynomial in $n$ of degree $k+1$, bounded explicitly by $(k+2)(n+1)^{k+1}$. In
the extreme sparse case $k=1$, global acyclicity collapses this to an exact
\textbf{linear} count of $2n$ faces for the clique complex of a spanning tree. We
complement these counting results with a self-contained proof of the
capturing-face existence on the line ($d=1$), extracting from the honest
hypothesis ``$0$ lies in the convex hull of each color class'' a rainbow edge
whose convex hull contains the origin. Together these results show that a
capturing face always exists and can be certified inside a spanning-tree-sized
--- linear, for $k=1$ --- sub-collection of the join rather than the full
exponential complex.
\end{abstract}

\noindent\textbf{Keywords:} colorful Carath\'eodory theorem, spanning $k$-tree,
join of point sets, convex hull, witness complexity, simplicial complex,
acyclicity, face enumeration, computational geometry.

\section{Introduction}

\subsection{Background}
Carath\'eodory's classical theorem states that if a point $p \in \R^d$ lies in
the convex hull of a set $S$, then $p$ lies in the convex hull of some subset of
$S$ of at most $d+1$ points. B\'ar\'any's \emph{colorful Carath\'eodory theorem}
(1982) is a striking strengthening: rather than drawing all $d+1$ points from a
single set, one may draw one point from each of $d+1$ distinct ``color classes,''
provided each color class individually captures $p$.

\begin{theorem}[Colorful Carath\'eodory, B\'ar\'any 1982]
Let $V_1, \dots, V_{d+1} \subseteq \R^d$ be finite sets and $p \in \R^d$ a point
such that $p \in \conv(V_i)$ for every $i$. Then there exist points $v_1 \in V_1,
\dots, v_{d+1} \in V_{d+1}$ with $p \in \conv\{v_1, \dots, v_{d+1}\}$.
\end{theorem}

The selected simplex $\{v_1, \dots, v_{d+1}\}$ is \emph{rainbow}: it uses exactly
one vertex of each color. This theorem is a cornerstone of combinatorial
geometry, underlying Tverberg's theorem, the First Selection Lemma, and the
fastest known algorithms for computing approximate centerpoints and Tverberg
partitions.

\subsection{The quantitative question}
Combinatorially, the collection of all rainbow simplices is the \emph{join}
$V_1 * V_2 * \cdots * V_{d+1}$, whose top-dimensional faces number
$\prod_{i=1}^{d+1} |V_i|$. This is exponential in the number of color classes, so
a brute-force search over the join is intractable. The qualitative theorem
asserts a capturing face exists \emph{somewhere} in the join. We ask the sharper
question: what is the size of the smallest sub-collection of faces of the join
that is guaranteed to contain a $p$-capturing face? We show the answer is governed
by two independent parameters of the certifying complex: its \emph{width} and its
\emph{global acyclicity}.

\subsection{Contributions}
\begin{enumerate}
\item Exact face count of bounded-width complexes (Theorem~\ref{thm:skel}).
\item Polynomial witness bound (Theorems~\ref{thm:bound} and~\ref{thm:poly}).
\item Linear collapse for trees (Theorem~\ref{thm:tree}).
\item Capturing-face existence on the line (Theorem~\ref{thm:cc1}).
\item Synthesis of witness size (Theorem~\ref{thm:synth}).
\end{enumerate}

\section{Definitions}

\begin{definition}[Abstract complex, face, width]
An \emph{abstract complex} $K$ on a ground set of vertices is a finite family of
finite vertex sets, called \emph{faces}. The \emph{width} of $K$ is
$\max_{s \in K} |s|$. We say $K$ has width at most $m$ if $|s| \le m$ for every
$s \in K$.
\end{definition}

\begin{definition}[Skeleton]
The \emph{$m$-skeleton} of a ground set $B$ is $\Skel_m(B) = \{\, t \subseteq B :
|t| \le m \,\}$, the largest complex of width $\le m$ on $B$.
\end{definition}

\begin{definition}[Spanning $k$-tree]
A \emph{$d$-dimensional spanning $k$-tree} $K$ on a vertex set $B$ is a
simplicial complex that (i) \emph{spans} $B$, (ii) has width at most $k+1$, and
(iii) is assembled acyclically. For $k=1$ this specializes to an ordinary
spanning tree of a graph, whose faces are the empty set, the vertices, and the
edges.
\end{definition}

\begin{definition}[Clique complex]
For a simple graph $G$ on vertex set $V$, its \emph{clique complex} has as faces
all cliques of $G$. For a tree $G$ (triangle-free), the faces are the empty set,
the singletons, and the edges.
\end{definition}

\begin{definition}[Join and rainbow face]
For finite point sets $V_1, \dots, V_{d+1}$, the \emph{join} $V_1 * \cdots *
V_{d+1}$ is the complex whose faces choose at most one vertex from each color
class. A \emph{rainbow} face chooses exactly one vertex per color class.
\end{definition}

\begin{definition}[Convex hull, capturing, witness]
For $S \subseteq \R^d$, $\conv(S)$ is the set of finite convex combinations of
points of $S$. A face $\sigma$ \emph{captures} $p$ if $p \in \conv(\sigma)$. A
\emph{witness complex} is a sub-collection $K$ of the join's faces such that some
$\sigma \in K$ captures $p$; the \emph{witness complexity} is the minimum $|K|$
over a specified structural family.
\end{definition}

\section{Face counts of bounded-width complexes}

\begin{lemma}[Level-set decomposition]\label{lem:level}
For a finite ground set $B$ and integer $m$,
$\{\, t \subseteq B : |t| \le m \,\} = \bigsqcup_{i=0}^{m} \binom{B}{i}$,
where $\binom{B}{i}$ denotes the subsets of $B$ of size exactly $i$.
\end{lemma}
\begin{proof}
A set $t \subseteq B$ satisfies $|t| \le m$ iff $|t| = i$ for some
$i \in \{0, \dots, m\}$. The union is disjoint since a set has a unique
cardinality.
\end{proof}

\begin{theorem}[Exact face count of the $m$-skeleton]\label{thm:skel}
For a ground set $B$ with $|B| = n$,
$\bigl|\Skel_m(B)\bigr| = \sum_{i=0}^{m} \binom{n}{i}$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:level} the skeleton is the disjoint union of the level sets
$\binom{B}{i}$ for $i \le m$; each has $\binom{n}{i}$ elements. Summing over the
disjoint pieces gives the claim.
\end{proof}

The right-hand side is a polynomial in $n$ of degree $m$ with leading term
$n^m/m!$.

\begin{theorem}[Polynomial witness bound, exact form]\label{thm:bound}
Let $K$ be any complex of width at most $m$ on a ground set $B$ with $|B| = n$.
Then $|K| \le \sum_{i=0}^{m} \binom{n}{i}$.
\end{theorem}
\begin{proof}
Every face of $K$ is a subset of $B$ of size at most $m$, so $K \subseteq
\Skel_m(B)$. Monotonicity of cardinality and Theorem~\ref{thm:skel} give the
bound.
\end{proof}

\begin{lemma}[Polynomial domination]\label{lem:dom}
For all $n, m \ge 0$, $\ \sum_{i=0}^{m} \binom{n}{i} \le (m+1)\,(n+1)^{m}$.
\end{lemma}
\begin{proof}
For each $i \le m$, $\binom{n}{i} \le n^i \le (n+1)^i \le (n+1)^m$. The sum has
$m+1$ terms, each at most $(n+1)^m$.
\end{proof}

\begin{theorem}[Polynomial-size witness for a spanning $k$-tree]\label{thm:poly}
Let $K$ be a complex of width at most $k+1$ on a ground set $B$ with $|B| = n$ ---
in particular, a $d$-dimensional spanning $k$-tree. Then
$|K| \le (k+2)\,(n+1)^{k+1}$, a polynomial in $n$ of degree $k+1$.
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:bound} with $m = k+1$, then Lemma~\ref{lem:dom} with
$m = k+1$.
\end{proof}

\begin{remark}[Tightness]
The degree $k+1$ is best possible for width-$(k+1)$ complexes: the full
$(k+1)$-skeleton attains the exact sum of Theorem~\ref{thm:skel}, with leading
term $n^{k+1}/(k+1)!$. Improving the degree requires structure beyond bounded
width.
\end{remark}

\section{The $k=1$ collapse: spanning trees have linear witnesses}

\begin{theorem}[Linear face count of a spanning tree]\label{thm:tree}
Let $G$ be a tree on a finite vertex set $V$ with $|V| = n$. Then the clique
complex of $G$ has exactly $2n$ faces:
$1 + n + (n-1) = 2n$.
\end{theorem}
\begin{proof}
A tree is connected and acyclic, so it has exactly $n-1$ edges (the identity
$|E| + 1 = |V|$). Being triangle-free, its cliques are the empty set, the $n$
singletons, and the $n-1$ edges. Hence the face count is $1 + n + (n-1) = 2n$.
\end{proof}

\begin{remark}[Structure beats width]
A generic width-$2$ complex may have up to $\binom{n}{2} \approx n^2/2$ edges, so
its face count is quadratic. The tree's linear count is a consequence of
\emph{acyclicity}, which caps the number of edges at $n-1$. Width sets the
polynomial degree; acyclicity collapses the degree at $k=1$.
\end{remark}

\section{The captured face exists: colorful Carath\'eodory on the line}

\begin{theorem}[Sign extraction]\label{thm:sign}
Let $V \subseteq \R$ be a nonempty finite set with $0 \in \conv(V)$. Then $V$
contains a nonpositive element and a nonnegative element.
\end{theorem}
\begin{proof}
Let $a = \min V$, $b = \max V$. Every element of $V$ lies in $[a,b]$, which is
convex, so $\conv(V) \subseteq [a,b]$. Hence $0 \in [a,b]$, i.e. $a \le 0 \le b$,
giving the nonpositive $a \in V$ and the nonnegative $b \in V$.
\end{proof}

\begin{theorem}[Segment through the origin]\label{thm:seg}
If $x \le 0 \le y$ in $\R$, then $0 \in [x, y]$.
\end{theorem}
\begin{proof}
If $x = y = 0$ this is trivial. Otherwise set $\lambda = y/(y-x)$ and
$\mu = -x/(y-x)$. Then $\lambda, \mu \ge 0$, $\lambda + \mu = 1$, and
$\lambda x + \mu y = (xy - xy)/(y-x) = 0$, exhibiting $0$ as a convex combination.
\end{proof}

\begin{theorem}[Colorful Carath\'eodory in dimension one]\label{thm:cc1}
Let $V_1, V_2 \subseteq \R$ be nonempty finite color classes with
$0 \in \conv(V_1)$ and $0 \in \conv(V_2)$. Then there is a rainbow edge
$\{x, y\}$ with $x \in V_1$, $y \in V_2$, and $0 \in \conv\{x, y\}$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:sign} extract $x \in V_1$ with $x \le 0$ and $y \in V_2$ with
$y \ge 0$. By Theorem~\ref{thm:seg}, $0 \in [x, y] = \conv\{x, y\}$. The edge uses
one vertex per color, so it is rainbow.
\end{proof}

The captured edge $\{x, y\}$ is a single edge of the join $V_1 * V_2$.

\section{Synthesis: a small witness always suffices}

\begin{theorem}[Witness-size synthesis]\label{thm:synth}
Let $V_1, V_2 \subseteq \R$ be nonempty finite color classes capturing the
origin, and let $n = |V_1 \cup V_2|$. Then:
\begin{enumerate}
\item there is a rainbow edge of $V_1 * V_2$ capturing the origin;
\item any width-$2$ sub-complex $K$ of the join on the $n$-vertex ground set
satisfies $|K| \le 3(n+1)^2$;
\item if the witness is organized as a spanning tree, its face count is exactly
$2n$.
\end{enumerate}
\end{theorem}
\begin{proof}
Part 1 is Theorem~\ref{thm:cc1}. Part 2 is Theorem~\ref{thm:poly} with $k=1$,
giving $(1+2)(n+1)^{2} = 3(n+1)^2$. Part 3 is Theorem~\ref{thm:tree}.
\end{proof}

\section{Algorithms}

\begin{algo}[Rainbow edge on the line]
Given finite $V_1, V_2 \subseteq \R$ each capturing $0$: find a nonpositive
element $x \in V_1$ and a nonnegative element $y \in V_2$; return $\{x, y\}$. By
Theorem~\ref{thm:cc1} this edge captures $0$; the running time is linear in
$|V_1| + |V_2|$.
\end{algo}

\begin{algo}[Witness enumeration bound]
Given a width-$(k+1)$ certifying complex on $n$ vertices, the number of candidate
faces is at most $(k+2)(n+1)^{k+1}$, and exactly $2n$ if the complex is a spanning
tree, replacing the exponential $\prod_i |V_i|$ enumeration of the full join.
\end{algo}

\section{Applications}
\begin{itemize}
\item \textbf{Centerpoint and Tverberg computation.} Colorful Carath\'eodory
drives the fastest known approximate-centerpoint and Tverberg-partition
algorithms; bounding witness size limits the per-iteration search.
\item \textbf{Data depth and robust statistics.} Efficient witnesses translate to
faster depth-based estimators.
\item \textbf{Certificate design.} The two-lever principle (width sets the degree,
acyclicity collapses it) is a reusable template for turning existence theorems
into small certificates.
\end{itemize}

\section{Discussion}
Width is a local constraint bounding the face count by a polynomial of degree
equal to the width; acyclicity is a global constraint that caps the number of top
faces, collapsing the polynomial to linear at $k=1$. The generic degree-$(k+1)$
bound is tight, so the linear tree count is a structural gain. Geometrically, the
one-dimensional proof exposes the honest input: capturing the origin is
equivalent to straddling it in sign.

\section{Future directions}

\begin{conjecture}[Sharp linear witnesses for every fixed width]
For every fixed $k$, a spanning $k$-tree on $n$ vertices has face count linear in
$n$, at most $2^{k}(n-k) + (2^{k+1}-1)$, strictly below the degree-$(k+1)$ bound
for arbitrary width-$(k+1)$ complexes. Each newly attached vertex contributes a
bounded number of new cliques, so the total grows additively; the $k=1$ case
(exact $2n$) isolates acyclicity as the collapse mechanism.
\end{conjecture}

\begin{conjecture}[Rainbow capture inside a spanning tree of the join]
For color classes on the line whose hulls contain the origin, one can pre-select
a spanning tree of the join $V_1 * V_2$ --- of only linearly many edges ---
guaranteed to contain a rainbow edge through the origin, so the exponential join
never needs examination. A single monotone matching of nonpositive to nonnegative
points meets the sign-determined crossing pattern.
\end{conjecture}

\begin{conjecture}[Higher-dimensional sign extraction]
In $\R^d$, if the origin lies in $\conv(V)$ for a finite color class $V$, then $V$
contains an affinely independent sub-family of at most $d+1$ points whose hull
captures the origin, locatable by examining only polynomially many
$(d+1)$-subsets when restricted to a spanning $d$-tree of $V$. The extreme-point
selection $\min, \max$ of the one-dimensional argument generalizes to
barycentric-coordinate support on a bounded face.
\end{conjecture}

\section{Conclusion}
A capturing face always exists (proved explicitly on the line), and it can be
certified inside a bounded-width complex whose face count is polynomial of degree
$k+1$ --- exactly $\sum_{i=0}^{k+1}\binom{n}{i} \le (k+2)(n+1)^{k+1}$ ---
collapsing to a linear $2n$ for spanning trees. The exponential join is never
needed. Width and acyclicity emerge as the two independent controls on witness
size.

