"""Demo: exact face count of a width-m skeleton equals sum_{i<=m} C(n,i)."""
from __future__ import annotations
from itertools import combinations
from math import comb


def skeleton_face_count(n: int, m: int) -> int:
    """Closed-form face count of the width-m skeleton on n vertices."""
    return sum(comb(n, i) for i in range(m + 1))


def skeleton_face_count_bruteforce(n: int, m: int) -> int:
    """Brute-force count of subsets of {0,...,n-1} of size at most m."""
    total = 0
    for size in range(m + 1):
        total += sum(1 for _ in combinations(range(n), size))
    return total


if __name__ == "__main__":
    for n in range(3, 9):
        for m in (1, 2, 3):
            exact = skeleton_face_count(n, m)
            brute = skeleton_face_count_bruteforce(n, m)
            assert exact == brute
            print(f"n={n}, m={m}: faces={exact} (degree-{m} polynomial in n)")

"""Demo: a spanning tree on n vertices has exactly 2n clique-complex faces,
beating the generic quadratic width-2 bound."""
from __future__ import annotations
from math import comb
from typing import List, Tuple


def spanning_tree_face_count(n: int) -> int:
    """1 empty face + n vertices + (n-1) edges = 2n."""
    if n == 0:
        return 1
    return 1 + n + (n - 1)


def path_tree_edges(n: int) -> List[Tuple[int, int]]:
    """A concrete tree: the path 0-1-...-(n-1)."""
    return [(i, i + 1) for i in range(n - 1)]


if __name__ == "__main__":
    for n in (1, 2, 5, 10, 25, 100):
        tree = spanning_tree_face_count(n)
        generic = sum(comb(n, i) for i in range(3))  # width-2 skeleton
        edges = path_tree_edges(n)
        assert 1 + n + len(edges) == 2 * n == tree
        print(f"n={n:3d}: tree faces={tree:4d} (=2n)  generic width-2={generic}")

"""Demo: colorful Caratheodory on the line -- extract a rainbow edge {x,y}
through the origin from two color classes each capturing 0."""
from __future__ import annotations
from typing import Optional, Sequence, Tuple


def captures_origin(cls: Sequence[float]) -> bool:
    """0 in conv(cls) iff min(cls) <= 0 <= max(cls)."""
    return bool(cls) and min(cls) <= 0.0 <= max(cls)


def rainbow_edge(v1: Sequence[float], v2: Sequence[float]
                 ) -> Optional[Tuple[float, float, float, float]]:
    """Return (x, y, lambda, mu) with x in v1<=0, y in v2>=0 and
    lambda*x + mu*y = 0, or None if a hypothesis fails."""
    if not captures_origin(v1) or not captures_origin(v2):
        return None
    x = max(v for v in v1 if v <= 0.0)
    y = min(v for v in v2 if v >= 0.0)
    if x == 0.0 and y == 0.0:
        return (x, y, 1.0, 0.0)
    lam, mu = y / (y - x), -x / (y - x)
    return (x, y, lam, mu)


if __name__ == "__main__":
    tests = [([-3.0, -1.0, 2.0], [-0.5, 1.0, 4.0]),
             ([-2.0, 5.0], [-1.0, 0.5, 3.0]),
             ([0.0, 7.0], [-4.0, 6.0])]
    for v1, v2 in tests:
        res = rainbow_edge(v1, v2)
        assert res is not None
        x, y, lam, mu = res
        assert abs(lam * x + mu * y) < 1e-12
        print(f"V1={v1}, V2={v2} -> edge ({x},{y}), 0={lam:.3f}*{x}+{mu:.3f}*{y}")

