function RainbowEdge(V1, V2):
    require min(V1) <= 0 <= max(V1)      # V1 captures 0
    require min(V2) <= 0 <= max(V2)      # V2 captures 0
    x <- any element of V1 with x <= 0   # e.g. max such element
    y <- any element of V2 with y >= 0   # e.g. min such element
    if x == 0 and y == 0:
        return (x, y, lambda=1, mu=0)
    lambda <- y / (y - x)
    mu     <- -x / (y - x)
    assert lambda >= 0 and mu >= 0 and lambda + mu == 1
    assert lambda*x + mu*y == 0
    return (x, y, lambda, mu)

