from typing import Optional, Sequence, Tuple


def rainbow_edge_on_line(v1: Sequence[float], v2: Sequence[float]
                         ) -> Optional[Tuple[float, float, float, float]]:
    """Return (x, y, lambda, mu) certifying 0 = lambda*x + mu*y with
    x in v1 (<=0), y in v2 (>=0), or None if either class fails to capture 0."""
    if not v1 or not v2:
        return None
    if not (min(v1) <= 0.0 <= max(v1)):
        return None
    if not (min(v2) <= 0.0 <= max(v2)):
        return None
    x = max(v for v in v1 if v <= 0.0)
    y = min(v for v in v2 if v >= 0.0)
    if x == 0.0 and y == 0.0:
        return (x, y, 1.0, 0.0)
    lam = y / (y - x)
    mu = -x / (y - x)
    return (x, y, lam, mu)

