function TreeWitnessFaces(V, E):
    n <- |V|
    require |E| == n - 1               # necessary for a tree
    require IsConnectedAcyclic(V, E)   # union-find: no cycle, one component
    faces <- { emptyset }
    for v in V: faces <- faces + { {v} }
    for e in E: faces <- faces + { e }
    assert |faces| == 2 * n
    return faces

