from __future__ import annotations
from typing import FrozenSet, List, Set, Tuple


def tree_witness_faces(n: int, edges: List[Tuple[int, int]]
                       ) -> Set[FrozenSet[int]]:
    """Enumerate faces of the clique complex of a tree on vertices 0..n-1.
    Raises ValueError if (n, edges) is not a tree. Returns a set of 2n faces."""
    if len(edges) != n - 1:
        raise ValueError("a tree on n vertices has exactly n-1 edges")
    parent = list(range(n))

    def find(a: int) -> int:
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    for u, v in edges:
        ru, rv = find(u), find(v)
        if ru == rv:
            raise ValueError("edges contain a cycle; not a tree")
        parent[ru] = rv
    if len({find(i) for i in range(n)}) != 1:
        raise ValueError("graph is disconnected; not a tree")

    faces: Set[FrozenSet[int]] = {frozenset()}
    for v in range(n):
        faces.add(frozenset({v}))
    for u, v in edges:
        faces.add(frozenset({u, v}))
    assert len(faces) == 2 * n
    return faces
